def put(lang_i, name, rows):
    path = os.path.join(here, 'lots', name)
    with open(path, 'w', encoding='utf-8') as f:
        for r in rows:
            f.write(r[0] + '\t' + r[lang_i] + '\n')

for i, lang in ((1, 'en'), (2, 'es')):
    put(i, 'lot2.%s.tsv' % lang, E + C)
    put(i, 'lot2.motifs.%s.tsv' % lang, M)
